export function getSCRIPTURE_MEMORY_CURRICULUMLevel(levelNumber: number): CurriculumLevelData {
  const safeLevel = Math.max(1, Math.min(100, levelNumber));
  return SCRIPTURE_MEMORY_CURRICULUM_LEVELS[safeLevel - 1];
}
